settings.css:
#newborn-preview-ready-page {

  --sn-coral: #F43357;
  --sn-font-body: 'Poppins', sans-serif;
  --sn-font-heading: 'Playfair Display', serif;
  --sn-max-width: 1200px;
  --sn-navy: #1F293B;
  --sn-text-light: #94A3B8;
  --sn-white: #FFFFFF;

  --c-coral: #F43357;
  --c-coral-hover: #D62646;
  --c-navy: #1F293B;
  --c-cream: #FAF7F4;
  --c-beige: #F2EDEA;
  --c-white: #FFFFFF;
  --c-sage: #7C8A98;
  --c-yellow: #FFC107;
  --c-text: #161E2A;
  --c-muted: #64748B;

  --font-body: 'Poppins', sans-serif;
  --font-head: 'Playfair Display', serif;

  --radius: 20px;
  --shadow-card: 0 4px 20px rgba(0,0,0,0.06);
  --shadow-pop: 0 10px 30px rgba(0,0,0,0.12);
  --shadow-soft: 0 2px 10px rgba(0,0,0,0.06);
  --ring: 0 0 0 4px rgba(244, 51, 87, 0.18);

  width: 100%;
  overflow-x: hidden;
  font-family: var(--font-body);
  color: var(--c-text);
  line-height: 1.6;
  background: var(--c-cream);
  isolation: isolate;
}

#newborn-preview-ready-page *,
#newborn-preview-ready-page *::before,
#newborn-preview-ready-page *::after { box-sizing: border-box; }
#newborn-preview-ready-page img { max-width: 100%; height: auto; display: block; }
#newborn-preview-ready-page a { text-decoration: none; transition: 0.3s ease; }

#newborn-preview-ready-page h1, #newborn-preview-ready-page h2, #newborn-preview-ready-page h3, #newborn-preview-ready-page h4 {
  font-family: var(--font-head);
  color: var(--c-navy);
  line-height: 1.2;
  margin-bottom: 1rem;
}
#newborn-preview-ready-page h1 { font-size: clamp(2.2rem, 5vw, 3.5rem); }
#newborn-preview-ready-page h2 { font-size: clamp(1.8rem, 4vw, 2.8rem); }
#newborn-preview-ready-page h3 { font-size: clamp(1.2rem, 3vw, 1.8rem); }

#newborn-preview-ready-page .npr-wrap {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  width: 100%;
}
#newborn-preview-ready-page .npr-band { padding: 48px 0; }
#newborn-preview-ready-page .npr-band.bg-white + .npr-band.bg-white { padding-top: 0; }
#newborn-preview-ready-page .bg-white { background: var(--c-white); }
#newborn-preview-ready-page .bg-cream { background: var(--c-cream); }
#newborn-preview-ready-page .text-center { text-align: center; }
#newborn-preview-ready-page .max-800 { max-width: 800px; margin: 0 auto; }

#newborn-preview-ready-page .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 32px;
  background: var(--c-coral);
  color: white;
  font-weight: 600;
  border-radius: 50px;
  border: none;
  cursor: pointer;
  min-height: 48px;
  box-shadow: 0 6px 18px rgba(244, 51, 87, 0.22);
  letter-spacing: 0.1px;
}
#newborn-preview-ready-page .btn:hover { background: var(--c-coral-hover); transform: translateY(-2px); color: white; }
#newborn-preview-ready-page .btn-outline {
  background: transparent;
  border: 1px solid rgba(244, 51, 87, 0.45);
  color: var(--c-coral);
  box-shadow: none;
}
#newborn-preview-ready-page .btn-outline:hover {
  background: rgba(244, 51, 87, 0.08);
  border-color: rgba(244, 51, 87, 0.7);
  color: var(--c-coral);
}

#newborn-preview-ready-page .hero-wrap {
  padding-top: 48px;
  padding-bottom: 32px;
}

#newborn-preview-ready-page .steps-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
  margin-top: 28px;
}
#newborn-preview-ready-page .step-card {
  background: white;
  padding: 26px;
  border-radius: var(--radius);
  text-align: center;
  box-shadow: var(--shadow-card);
  border: 1px solid rgba(15, 23, 42, 0.06);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
#newborn-preview-ready-page .step-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-pop); }

#newborn-preview-ready-page .npr-band {
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
}

@media (max-width: 768px) {
  #newborn-preview-ready-page .npr-band { padding: 36px 0; }
  #newborn-preview-ready-page .btn { width: 100%; }}


#newborn-preview-ready-page .npr-hero-lead {
  font-size: 1.1rem;
  color: var(--c-muted);
  margin: 0 auto 28px;
  max-width: 640px;
}

#newborn-preview-ready-page .npr-trial-note {
  font-size: 0.9rem;
  color: var(--c-muted);
  margin: 18px auto 0;
  max-width: 640px;
}

#newborn-preview-ready-page .npr-next-lead {
  font-size: 1.05rem;
  color: var(--c-text);
  max-width: 720px;
  margin: 0 auto;
}

#newborn-preview-ready-page .npr-membership-lead {
  font-size: 1.05rem;
  color: var(--c-text);
  max-width: 720px;
  margin: 0 auto 28px;
}

   .snooze-footer-clean {
     background-color: var(--sn-navy);
     color: var(--sn-white);
     padding: 60px 0 30px;
     font-family: var(--sn-font-body);
     margin-top: auto;
   }

   .sf-container {
     max-width: var(--sn-max-width);
     margin: 0 auto;
     padding: 0 24px;
   }

   .sf-grid {
     display: grid;
     grid-template-columns: 1fr;
     gap: 40px;
     margin-bottom: 60px;
   }

   @media (min-width: 768px) {
     .sf-grid { grid-template-columns: 1.5fr repeat(4, 1fr); gap: 30px; }}


   .sf-col { text-align: left; }
   .sf-logo {
     margin-bottom: 16px;
     display: flex;
     justify-content: flex-start;
     align-items: center;
   }
   .sf-logo a {
     text-decoration: none;
     display: inline-block;
     line-height: 1;
   }
   .sf-logo svg {
     height: auto;
     max-height: 52px;
     width: 150px;
     display: block !important;
     flex-shrink: 0;
   }
   .sf-logo a svg {
     visibility: visible !important;
     opacity: 1 !important;
   }
   .sf-logo-text { font-family: var(--sn-font-heading); font-size: 24px; color: var(--sn-white); display: block; margin-bottom: 16px; }
   .sf-tagline { color: var(--sn-text-light); font-size: 14px; line-height: 1.6; margin-bottom: 24px; max-width: 100%; }
   .sf-socials { display: flex; gap: 16px; justify-content: flex-start; }
   .sf-social-link { color: var(--sn-white); font-size: 13px; text-decoration: none; opacity: 0.8; transition: opacity 0.2s; }
   .sf-social-link:hover { opacity: 1; color: var(--sn-coral); }
   .sf-heading { color: #F43357 !important; font-size: 16px; font-weight: 600; margin: 0 0 20px 0; font-family: var(--sn-font-heading); }
   .sf-links { list-style: none; padding: 0; margin: 0; }
   .sf-links li { margin-bottom: 12px; text-align: left; }
   .sf-links a { color: var(--sn-text-light); text-decoration: none; font-size: 14px; transition: color 0.2s; }
   .sf-links a:hover { color: var(--sn-coral); }
   .sf-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 30px; text-align: center; }
   .sf-bottom p { color: rgba(255,255,255,0.4); font-size: 12px; margin: 0; }

   @media (max-width: 767px) {
     .snooze-footer-clean { padding: 40px 0 20px; }
     .sf-container { padding: 0 20px; }
     .sf-grid { gap: 24px; margin-bottom: 32px; }
     .sf-logo svg {
       max-height: 40px !important;
       width: 120px !important;
     }
     .sf-logo-text { font-size: 20px; margin-bottom: 12px; }
     .sf-tagline { font-size: 13px; margin-bottom: 16px; }
     .sf-socials { gap: 12px; flex-wrap: wrap; justify-content: flex-start; }
     .sf-social-link { font-size: 12px; }
     .sf-heading { font-size: 14px; margin-bottom: 12px; }
     .sf-links li { margin-bottom: 8px; }
     .sf-links a { font-size: 13px; }
     .sf-bottom { padding-top: 20px; }
     .sf-bottom p { font-size: 11px; }}
